// The long form, needed when you have to pass a key
function List({ entries }) {
  return entries.map((entry) => (
    <Fragment key={entry.id}>
      <dt>{entry.term}</dt>
      <dd>{entry.definition}</dd>
    </Fragment>
  ));
}

