function ProfileCard() {
  const name = "Grace Hopper";
  const role = "Computer Scientist";

  return (
    <>
      <h3>{name}</h3>
      <p>{role}</p>
    </>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<ProfileCard />);
